1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Human-in-the-Loop — Meta-Harness</title>
7	<style>
8	  :root {
9	    --bg: #0d1117;
10	    --surface: #161b22;
11	    --border: #30363d;
12	    --text: #c9d1d9;
13	    --muted: #8b949e;
14	    --accent: #58a6ff;
15	    --green: #3fb950;
16	    --red: #f85149;
17	    --yellow: #d2991d;
18	    --purple: #a371f7;
19	  }
20	  * { margin: 0; padding: 0; box-sizing: border-box; }
21	  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: var(--bg); color: var(--text); padding: 24px; }
22	  h1 { font-size: 20px; margin-bottom: 8px; }
23	  .subtitle { color: var(--muted); font-size: 13px; margin-bottom: 24px; }
24	  .layout { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
25	  .panel { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
26	  .panel-header {
27	    padding: 12px 16px; border-bottom: 1px solid var(--border);
28	    font-size: 14px; font-weight: 600; display: flex; align-items: center; gap: 8px;
29	  }
30	  .panel-header .dot { width: 8px; height: 8px; border-radius: 50%; }
31	  .panel-header .dot.active { background: var(--green); }
32	  .panel-header .dot.baseline { background: var(--muted); }
33	  .panel-body { padding: 16px; }
34	  .panel-body pre { font-size: 12px; white-space: pre-wrap; word-break: break-all; max-height: 180px; overflow-y: auto; }
35	  .diff { font-family: 'SF Mono', 'Fira Code', monospace; font-size: 12px; line-height: 1.5; }
36	  .diff-add { color: var(--green); }
37	  .diff-rem { color: var(--red); }
38	  .diff-hunk { color: var(--muted); }
39	  .score { font-size: 24px; font-weight: 700; }
40	  .score-label { font-size: 11px; color: var(--muted); }
41	  .feedback-section { margin-top: 24px; }
42	  .feedback-section h2 { font-size: 16px; margin-bottom: 12px; }
43	  .feedback-form { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 16px; }
44	  .form-group { margin-bottom: 12px; }
45	  .form-group label { display: block; font-size: 13px; margin-bottom: 4px; color: var(--muted); }
46	  .form-group textarea {
47	    width: 100%; min-height: 80px; padding: 8px; font-size: 13px; font-family: 'SF Mono', 'Fira Code', monospace;
48	    background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; resize: vertical;
49	  }
50	  .form-group select {
51	    padding: 6px 12px; font-size: 13px;
52	    background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px;
53	  }
54	  .btn-row { display: flex; gap: 8px; }
55	  .btn {
56	    padding: 8px 16px; font-size: 13px; font-weight: 600; border-radius: 6px; cursor: pointer;
57	    border: 1px solid transparent; transition: opacity 0.15s;
58	  }
59	  .btn:hover { opacity: 0.85; }
60	  .btn-approve { background: var(--green); color: #000; }
61	  .btn-reject { background: var(--red); color: #fff; }
62	  .btn-revise { background: var(--yellow); color: #000; }
63	  .btn-skip { background: transparent; border-color: var(--border); color: var(--muted); }
64	  .history { margin-top: 24px; }
65	  .history h2 { font-size: 16px; margin-bottom: 12px; }
66	  .history-item {
67	    background: var(--surface); border: 1px solid var(--border); border-radius: 6px;
68	    padding: 12px 16px; margin-bottom: 8px; display: flex; align-items: center; gap: 12px;
69	  }
70	  .history-badge {
71	    font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 12px;
72	    text-transform: uppercase;
73	  }
74	  .history-badge.approved { background: rgba(63,185,80,0.15); color: var(--green); }
75	  .history-badge.rejected { background: rgba(248,81,73,0.15); color: var(--red); }
76	  .history-badge.revised { background: rgba(210,153,29,0.15); color: var(--yellow); }
77	  .history-meta { font-size: 12px; color: var(--muted); }
78	  .empty { color: var(--muted); font-style: italic; text-align: center; padding: 24px; }
79	</style>
80	</head>
81	<body>
82	<h1>Human-in-the-Loop Review</h1>
83	<p class="subtitle">
84	  Review candidate harnesses, provide feedback, and guide the next iteration.
85	  Candidates loaded from <code>.metaharness/candidates/</code>. Feedback written to <code>.metaharness/feedback/</code>.
86	</p>
87	
88	<div class="layout">
89	  <!-- Baseline -->
90	  <div class="panel">
91	    <div class="panel-header">
92	      <span class="dot baseline"></span> Baseline
93	      <span style="font-size:11px;color:var(--muted);margin-left:auto;">current</span>
94	    </div>
95	    <div class="panel-body">
96	      <div class="score" style="color:var(--muted);">4/10</div>
97	      <div class="score-label">search-set pass rate</div>
98	      <pre>function processResponse(data) {
99	  const result = data.result;
100	  return transform(result);
101	}</pre>
102	    </div>
103	  </div>
104	
105	  <!-- Candidate -->
106	  <div class="panel">
107	    <div class="panel-header">
108	      <span class="dot active"></span> Candidate <code>candidate_001</code>
109	      <span style="font-size:11px;color:var(--green);margin-left:auto;">new</span>
110	    </div>
111	    <div class="panel-body">
112	      <div class="score" style="color:var(--green);">7/10</div>
113	      <div class="score-label">search-set pass rate (+3)</div>
114	      <pre class="diff">
115	<span class="diff-hunk">@@ -1,3 +1,5 @@</span>
116	 function processResponse(data) {
117	<span class="diff-add">+  if (!data || !data.result) return null;</span>
118	   const result = data.result;
119	   return transform(result);
120	 }</pre>
121	    </div>
122	  </div>
123	</div>
124	
125	<!-- Feedback form -->
126	<div class="feedback-section">
127	  <h2>Provide Feedback</h2>
128	  <div class="feedback-form">
129	    <div class="form-group">
130	      <label>Decision</label>
131	      <select>
132	        <option value="approve">Approve — merge candidate</option>
133	        <option value="revise">Revise — apply suggestions below</option>
134	        <option value="reject">Reject — discard and retry</option>
135	        <option value="skip">Skip — move to next candidate</option>
136	      </select>
137	    </div>
138	    <div class="form-group">
139	      <label>Feedback (written to <code>.metaharness/feedback/</code>)</label>
140	      <textarea placeholder="e.g. The null-check is good, but also handle empty string responses. Consider adding a timeout guard on the retry loop."></textarea>
141	    </div>
142	    <div class="btn-row">
143	      <button class="btn btn-approve">Approve</button>
144	      <button class="btn btn-revise">Request Revision</button>
145	      <button class="btn btn-reject">Reject</button>
146	      <button class="btn btn-skip">Skip</button>
147	    </div>
148	  </div>
149	</div>
150	
151	<!-- Decision history -->
152	<div class="history">
153	  <h2>Review History</h2>
154	  <div class="history-item">
155	    <span class="history-badge approved">approved</span>
156	    <span style="flex:1">candidate_000 (baseline seed)</span>
157	    <span class="history-meta">2026-05-27 14:00:00</span>
158	  </div>
159	  <div class="history-item">
160	    <span class="history-badge revised">revised</span>
161	    <span style="flex:1">candidate_001 · "null-check looks good, also add timeout"</span>
162	    <span class="history-meta">2026-05-27 14:36:02</span>
163	  </div>
164	</div>
165	</body>
166	</html>
