21	  h1 { font-size: 20px; margin-bottom: 16px; }
22	  .timeline { position: relative; padding-left: 24px; border-left: 2px solid var(--border); }
23	  .step { margin-bottom: 24px; position: relative; }
24	  .step::before {
25	    content: '';
26	    position: absolute; left: -31px; top: 4px;
27	    width: 12px; height: 12px; border-radius: 50%;
28	    background: var(--surface); border: 2px solid var(--border);
29	  }
30	  .step.observe::before { border-color: var(--accent); background: var(--accent); }
31	  .step.diagnose::before { border-color: var(--yellow); background: var(--yellow); }
32	  .step.propose::before { border-color: var(--green); background: var(--green); }
33	  .step.evaluate::before { border-color: var(--red); background: var(--red); }
34	  .step.iterate::before { border-color: var(--muted); background: var(--muted); }
35	  .step-header { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
36	  .step-badge {
37	    font-size: 11px; font-weight: 600; text-transform: uppercase;
38	    padding: 2px 8px; border-radius: 12px; letter-spacing: 0.5px;
39	  }
40	  .observe .step-badge { background: rgba(88,166,255,0.15); color: var(--accent); }
41	  .diagnose .step-badge { background: rgba(210,153,29,0.15); color: var(--yellow); }
42	  .propose .step-badge { background: rgba(63,185,80,0.15); color: var(--green); }
43	  .evaluate .step-badge { background: rgba(248,81,73,0.15); color: var(--red); }
44	  .iterate .step-badge { background: rgba(139,148,158,0.15); color: var(--muted); }
45	  .step-time { font-size: 12px; color: var(--muted); }
46	  .step-body { background: var(--surface); border: 1px solid var(--border); border-radius: 6px; padding: 12px; }
47	  .step-body pre { font-size: 12px; white-space: pre-wrap; word-break: break-all; max-height: 200px; overflow-y: auto; }
48	  .diff { font-family: 'SF Mono', 'Fira Code', monospace; font-size: 12px; }
49	  .diff-add { color: var(--green); }
50	  .diff-rem { color: var(--red); }
51	  .diff-hunk { color: var(--muted); }
52	  .metric { display: inline-flex; gap: 4px; align-items: center; }
53	  .metric-value { font-weight: 600; font-size: 14px; }
54	  .metric-label { font-size: 11px; color: var(--muted); }
55	  .metrics-grid { display: flex; gap: 16px; margin-top: 8px; }
56	  .no-data { color: var(--muted); font-style: italic; }
57	</style>
58	</head>
59	<body>
60	<h1>Trajectory Viewer</h1>
61	<p style="color:var(--muted);font-size:13px;margin-bottom:24px;">
62	  Execution trace for candidate harness iteration. Data sourced from <code>.metaharness/traces/</code>.
63	</p>
64	
65	<div class="timeline">
66	  <!-- Step 1: Observe -->
67	  <div class="step observe">
68	    <div class="step-header">
69	      <span class="step-badge">Observe</span>
70	      <span class="step-time">Cycle 1 — 2026-05-27 14:32:01</span>
71	    </div>
72	    <div class="step-body">
73	      <div>Loaded 3 failed traces from <code>.metaharness/traces/</code></div>
74	      <ul style="margin:8px 0 0 16px;font-size:13px;">
75	        <li><code>trace_001.json</code> — 12 steps, exit code 1</li>
76	        <li><code>trace_002.json</code> — 8 steps, timeout</li>
77	        <li><code>trace_003.json</code> — 15 steps, assertion failure</li>
78	      </ul>
79	    </div>
80	  </div>
81	
82	  <!-- Step 2: Diagnose -->
83	  <div class="step diagnose">
84	    <div class="step-header">
85	      <span class="step-badge">Diagnose</span>
86	      <span class="step-time">Cycle 1 — 2026-05-27 14:33:12</span>
87	    </div>
88	    <div class="step-body">
89	      <div>Root cause analysis from trace inspection:</div>
90	      <pre>trace_001: Missing null-check on response object (line 47)
91	trace_002: Infinite retry loop — backoff not applied after 429
92	trace_003: Expected {"status":"ok"} but got {"status":"error","code":500}</pre>
93	    </div>
94	  </div>
95	
96	  <!-- Step 3: Propose -->
97	  <div class="step propose">
98	    <div class="step-header">
99	      <span class="step-badge">Propose</span>
100	      <span class="step-time">Cycle 1 — 2026-05-27 14:34:45</span>
101	    </div>
102	    <div class="step-body">
103	      <div>Candidate written to <code>.metaharness/candidates/candidate_001.json</code></div>
104	      <pre class="diff">
105	<span class="diff-hunk">@@ -45,7 +45,9 @@</span>
106	 function processResponse(data) {
107	<span class="diff-add">+  if (!data || !data.result) return null;</span>
108	   const result = data.result;
109	<span class="diff-hunk">@@ -102,5 +104,6 @@</span>
110	 async function retryRequest(url) {
111	<span class="diff-add">+  await backoff(attempt);</span>
112	   return fetch(url);
113	 }</pre>
114	    </div>
115	  </div>
116	
117	  <!-- Step 4: Evaluate -->
118	  <div class="step evaluate">
119	    <div class="step-header">
120	      <span class="step-badge">Evaluate</span>
121	      <span class="step-time">Cycle 1 — 2026-05-27 14:36:02</span>
122	    </div>
123	    <div class="step-body">
124	      <div>Search-set evaluation complete. Results written to <code>.metaharness/feedback/eval_001.json</code></div>
125	      <div class="metrics-grid">
126	        <div class="metric">
127	          <span class="metric-value" style="color:var(--green);">7/10</span>
128	          <span class="metric-label">pass</span>
129	        </div>
130	        <div class="metric">
131	          <span class="metric-value" style="color:var(--red);">3</span>
132	          <span class="metric-label">remaining failures</span>
133	        </div>
134	      </div>
135	    </div>
136	  </div>
137	
138	  <!-- Step 5: Iterate -->
139	  <div class="step iterate">
140	    <div class="step-header">
141	      <span class="step-badge">Iterate</span>
142	      <span class="step-time">Cycle 1 — 2026-05-27 14:36:15</span>
143	    </div>
144	    <div class="step-body">
145	      <div>3 remaining failures. Continuing to next cycle...</div>
146	    </div>
147	  </div>
148	</div>
149	</body>
150	</html>
