92	<h1>Commit Review</h1>
93	<p class="sub"><strong>Message:</strong> $GOAL &mdash; <strong>Version:</strong> $VERSION &mdash; <strong>Hash:</strong> $SHORT_HASH</p>
94	
95	<div class="section">
96	  <h2><span class="letter">A</span> Staged Changes</h2>
97	  <div class="diff-box">$(git diff --cached --stat | head -30)</div>
98	</div>
99	
100	<div class="section">
101	  <h2><span class="letter">B</span> Files Changed</h2>
102	  <div class="diff-box">$(git diff --cached --name-only)</div>
103	</div>
104	
105	<div class="section">
106	  <h2><span class="letter">C</span> Decision</h2>
107	  <div class="verdict go" id="verdict-go" style="display:none">GO — commit will proceed</div>
108	  <div class="verdict" style="background:rgba(198,69,69,0.08);border:1px solid rgba(198,69,69,0.25);color:var(--red);display:none" id="verdict-nogo">NO-GO — commit will be blocked</div>
109	  <p style="font-size:14px;color:var(--body);margin-bottom:12px;">Review the changes above. Click GO to allow the commit, or NO-GO to block it.</p>
110	  <div class="btn-row">
111	    <button class="btn btn-go" onclick="decide('go')">GO — Allow Commit</button>
112	    <button class="btn btn-nogo" onclick="decide('nogo')">NO-GO — Block Commit</button>
113	  </div>
114	  <div id="status"></div>
115	</div>
116	
117	<script>
118	async function decide(d) {
119	  document.querySelector('#status').textContent = 'Submitting...';
120	  try {
121	    await fetch('http://127.0.0.1:8767/submit-feedback', {
122	      method: 'POST',
123	      headers: {'Content-Type': 'application/json'},
124	      body: JSON.stringify({decision: d, short_hash: '$SHORT_HASH', timestamp: new Date().toISOString()})
125	    });
126	    document.querySelector('#verdict-' + d).style.display = 'block';
127	    document.querySelector('.btn-row').style.display = 'none';
128	    document.querySelector('#status').textContent = d === 'go' ? 'Decision submitted: GO. You may close this tab.' : 'Decision submitted: NO-GO. Commit blocked.';
