  .diff-box { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 16px; font-family: 'JetBrains Mono', 'SF Mono', monospace; font-size: 13px; white-space: pre-wrap; max-height: 200px; overflow-y: auto; color: var(--body); margin-bottom: 12px; }
