# ── Step 2: Generate review artifacts ──
if [ -f "$METRIC_SCRIPT" ]; then
    python "$METRIC_SCRIPT" --diff HEAD --goal "$GOAL" --output /dev/null 2>&1 || true
fi

# Generate human-loop from reference template
HUMAN_LOOP="$OUTDIR/human-loop-$SHORT_HASH.html"
if [ -f "$SURVEY_SCRIPT" ]; then
    python "$SURVEY_SCRIPT" --type human-loop --version "$VERSION" --output "$HUMAN_LOOP" 2>&1 || true
else
    # Fallback: minimal HTML shell
    cat > "$HUMAN_LOOP" <<'FALLBACK'
<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><title>Commit Review</title></head>
<body><h1>Commit Review</h1><pre>FALLBACK
    git diff --cached --stat >> "$HUMAN_LOOP"
    echo '</pre></body></html>' >> "$HUMAN_LOOP"
fi

# Inject staged diff + decision form into generated survey
if [ -f "$HUMAN_LOOP" ]; then
    STAGED_DIFF=$(git diff --cached --stat | head -40)
    STAGED_NAMES=$(git diff --cached --name-only)
    python -c "
import sys
html = open('$HUMAN_LOOP', 'r', encoding='utf-8').read()

# Inject staged changes section before the first h2
diff_block = '''<div class=\"question ctx-block\">
  <h3>Staged Changes (this commit)</h3>
  <pre style=\"font-family:'JetBrains Mono',monospace;font-size:13px;white-space:pre-wrap;max-height:240px;overflow-y:auto;\">''' + '''$STAGED_DIFF''' + '''</pre>
</div>'''

